#if UNITY_EDITOR
using System;
using System.IO;
using UnityEditor;
using UnityEditor.Build.Reporting;
using UnityEditor.SceneManagement;
using UnityEngine;
namespace HimoHitoReviewTools
{
    // Editor-only packaging. No gameplay, presentation, scene or firewall edits.
    public static class ReviewRuntimeBuilder
    {
        static string Arg(string key){var a=Environment.GetCommandLineArgs();for(int i=0;i<a.Length-1;i++)if(a[i]==key)return a[i+1];throw new Exception("Missing "+key);}
        public static void Build()
        {
            try
            {
                string path=Arg("-reviewOutput");if(File.Exists(path))throw new Exception("Never overwrite an existing review runtime");
                EditorUserBuildSettings.development=false;
                EditorUserBuildSettings.allowDebugging=false;
                EditorUserBuildSettings.connectProfiler=false;
                EditorUserBuildSettings.buildWithDeepProfilingSupport=false;
                EditorSceneManager.OpenScene("Assets/Scenes/MainStage.unity");
                var options=new BuildPlayerOptions{scenes=new[]{"Assets/Scenes/MainStage.unity","Assets/Scenes/Tutorial.unity"},locationPathName=path,target=BuildTarget.StandaloneWindows64,options=BuildOptions.None};
                var report=BuildPipeline.BuildPlayer(options);
                File.WriteAllText(Path.Combine(Path.GetDirectoryName(path),"ReviewBuildSummary.json"),JsonUtility.ToJson(new Summary{result=report.summary.result.ToString(),errors=(int)report.summary.totalErrors,warnings=(int)report.summary.totalWarnings,bytes=(long)report.summary.totalSize,buildOptions=report.summary.options.ToString(),unity=Application.unityVersion},true));
                if(report.summary.result!=BuildResult.Succeeded||(report.summary.options&BuildOptions.Development)!=0)throw new Exception("Expected successful non-Development build");
                Debug.Log("FIXED_REVIEW_BUILD SUCCEEDED; Development=false; Profiler autoconnect=false; Script debugging=false");
                EditorApplication.Exit(0);
            }
            catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}
        }
        [Serializable]class Summary{public string result,buildOptions,unity;public int errors,warnings;public long bytes;}
    }
}
#endif
